-- ----------------------------
-- Table structure for strawberry_cluster
-- ----------------------------
DROP TABLE IF EXISTS `strawberry_cluster`;
CREATE TABLE `strawberry_cluster` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cluster_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '草莓簇/区域唯一ID',
  `cluster_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '区域/地块名称（例如：温室A北区）',
  `total_count` int DEFAULT NULL COMMENT '簇内草莓总数',
  `ripe_count` int DEFAULT NULL COMMENT '已成熟数量',
  `half_ripe_count` int DEFAULT NULL COMMENT '半成熟数量',
  `unripe_count` int DEFAULT NULL COMMENT '未成熟数量',
  `avg_size_mm` float DEFAULT NULL COMMENT '平均大小（毫米）',
  `location_area` geometry DEFAULT NULL COMMENT '区域范围（地块/簇）',
  `latitude` double DEFAULT NULL COMMENT '簇中心点纬度',
  `longitude` double DEFAULT NULL COMMENT '簇中心点经度',
  `recommendation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci COMMENT '系统生成的采摘建议采摘时间（由AI或定时任务写入）',
  `last_update` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cluster_id` (`cluster_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_is_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='草莓产量预期表';

