-- Records of strawberry_cluster
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for strawberry_pest_disease
-- ----------------------------
DROP TABLE IF EXISTS `strawberry_pest_disease`;
CREATE TABLE `strawberry_pest_disease` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cluster_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '对应草莓簇/区域ID',
  `object_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '检测对象类型：leaf（叶子）/ fruit（果实）/ stem（茎）',
  `bbox_x_min` float DEFAULT NULL COMMENT '边界框最小X坐标（目标检测框左上角X）',
  `bbox_y_min` float DEFAULT NULL COMMENT '边界框最小Y坐标（目标检测框左上角Y）',
  `bbox_x_max` float DEFAULT NULL COMMENT '边界框最大X坐标（目标检测框右下角X）',
  `bbox_y_max` float DEFAULT NULL COMMENT '边界框最大Y坐标（目标检测框右下角Y）',
  `confidence` float DEFAULT NULL COMMENT '检测置信度（0.0 ~ 1.0）',
  `pest_disease_class` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '识别出的病虫害类别（如：白粉病、红蜘蛛等）',
  `severity_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci DEFAULT NULL COMMENT '严重程度：low / medium / high',
  `recommendation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_is_0900_ai_ci COMMENT '系统生成的防治或处理建议（由AI或定时任务写入）',
  `detected_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '病虫害检测时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_is_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='病虫害分析表';

