INSERT INTO `knowledge_base` (`id`, `name`, `remark`, `file_name`, `user_id`, `upload_time`, `status`, `top_k`) VALUES (12, '草莓模型', '', '育苗期.md', NULL, '2025-08-22 09:20:47', 1, 5);
INSERT INTO `knowledge_base` (`id`, `name`, `remark`, `file_name`, `user_id`, `upload_time`, `status`, `top_k`) VALUES (13, '草莓预产量知识库', '', '育苗期.md', NULL, '2025-08-22 09:46:55', 1, 5);
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (192, 5, 0, '1. 产量预测逻辑', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (193, 5, 1, '- 产量计算基础：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (194, 5, 2, '   - 产量 ≈ 簇内草莓数量 × 平均大小 × 成熟率系数', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (195, 5, 3, '   - 成熟率系数由「成熟 / 半熟 / 未熟比例」决定。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (196, 5, 4, '- 分阶段产量：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (197, 5, 5, '   - 已成熟果：当前可采收量。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (198, 5, 6, '   - 半成熟果：预计 1–3 天成熟，产量需根据温度、光照条件进行修正。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (199, 5, 7, '   - 未成熟果：预计 3–7 天成熟，产量受营养供给和病虫害影响较大。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (200, 5, 8, '2. 影响因子（产量修正系数）', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (201, 5, 9, '- 环境因子：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (202, 5, 10, '   - 光照不足：果实重量减少 10–20%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (203, 5, 11, '   - 夜间温度过高（>25℃）：影响糖分积累，果实变小。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (204, 5, 12, '   - 湿度过大：易发生灰霉病，产量减少 15–30%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (205, 5, 13, '- 养分因子：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (206, 5, 14, '   - 氮肥过量→植株旺长，果实变小，产量下降。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (207, 5, 15, '   - 钾肥、钙肥充足→果实饱满，硬度提高，商品率提升 15–20%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (208, 5, 16, '- 病虫害因子：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (209, 5, 17, '   - 炭疽病果腐：直接损失产量。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (210, 5, 18, '   - 白粉病：降低光合效率，果实变小。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (211, 5, 19, '   - 灰霉病：采收前果实腐烂，产量损失显著。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (212, 5, 20, '3. 环境与产量关系', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (213, 5, 21, '- 空气温度', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (214, 5, 22, '   - 适宜范围：18–25℃。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (215, 5, 23, '   - <15℃：果实膨大慢，产量下降。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (216, 5, 24, '   - «30℃：光合作用受抑制，果实畸形率上升。»', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (217, 5, 25, '- 空气湿度', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (218, 5, 26, '   - 适宜范围：60–75%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (219, 5, 27, '   - «85%：灰霉病、白粉病风险高。»', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (220, 5, 28, '   - <40%：花粉活力下降，坐果率低。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (221, 5, 29, '- 光照强度', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (222, 5, 30, '   - 适宜范围：30,000–50,000 Lux。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (223, 5, 31, '   - 光照不足→果实变小、糖度降低。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (224, 5, 32, '- 二氧化碳', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (225, 5, 33, '   - 适宜浓度：800–1200 ppm。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (226, 5, 34, '   - <400 ppm：光合作用不足，产量下降 10–20%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (227, 5, 35, '4. 土壤与产量关系', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (228, 5, 36, '- 土壤温度', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (229, 5, 37, '   - 适宜范围：15–25℃。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (230, 5, 38, '   - <10℃：根系活力差。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (231, 5, 39, '   - «30℃：根系早衰。»', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (232, 5, 40, '- 土壤湿度', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (233, 5, 41, '   - 适宜范围：60–70%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (234, 5, 42, '   - «80%：根系缺氧，易烂根。»', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (235, 5, 43, '   - <40%：果实膨大不足。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (236, 5, 44, '- 电导率 (EC)', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (237, 5, 45, '   - 适宜值：0.8–1.2 mS/cm。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (238, 5, 46, '   - 过高：盐害，影响吸收。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (239, 5, 47, '- pH', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (240, 5, 48, '   - 适宜范围：5.5–6.5。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (241, 5, 49, '   - «7.0：铁、锰缺乏。»', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (242, 5, 50, '   - <5.0：根系活力下降。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (243, 5, 51, '- 氮 (N)', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (244, 5, 52, '   - 过量：徒长，果小。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (245, 5, 53, '   - 缺乏：叶片发黄，产量下降。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (246, 5, 54, '- 磷 (P)', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (247, 5, 55, '   - 促进根系和开花。缺乏→花少果少。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (248, 5, 56, '- 钾 (K)', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (249, 5, 57, '   - 促进果实膨大与糖分积累。缺乏→果实硬度低、糖度下降。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (250, 5, 58, '5. 专家建议（产量管理）', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (251, 5, 59, '- 采收管理：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (252, 5, 60, '   - 已成熟果：优先采摘，防止过熟。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (253, 5, 61, '   - 半成熟果：注意天气变化，连续阴雨需提前采收。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (254, 5, 62, '   - 未成熟果：保持光照与养分，避免积水。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (255, 5, 63, '- 养分补充：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (256, 5, 64, '   - 膨果期补充钾、钙肥，避免裂果。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (257, 5, 65, '   - 避免后期氮肥过量。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (258, 5, 66, '- 病害预防：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (259, 5, 67, '   - 产量预测需结合病害风险评估。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (260, 5, 68, '   - 在高湿环境下，需提前 2–3 天进行防病喷药。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (261, 5, 69, '根据环境与土壤条件，修正产量预测值：', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (262, 5, 70, '- 环境或养分超出适宜范围时，预估产量需降低 10–30%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (263, 5, 71, '- 条件适宜时，预估产量可上调 5–15%。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (264, 5, 72, '采收时机需结合土壤湿度、温度，避免雨后立即采收。', '2025-08-21 14:36:16');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (276, 10, 0, '1. Angular Leafspot（角斑病）', '2025-08-21 20:59:47');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (277, 10, 1, '- 病原与传播：由 Xanthomonas fragariae 引起，细菌性病害，主要通过雨水、灌溉水传播。', '2025-08-21 20:59:47');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (278, 10, 2, '- 症状：叶片出现水浸状小斑点，逐渐发展为褐色坏死斑，严重时叶片枯死。', '2025-08-21 20:59:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (279, 10, 3, '- 环境与诱发条件：', '2025-08-21 20:59:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (280, 10, 4, '   - 低温高湿（15–20℃）时易发；', '2025-08-21 20:59:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (281, 10, 5, '   - 高湿度环境（空气湿度 > 80%、土壤湿度过高）会加重病害。', '2025-08-21 20:59:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (282, 10, 6, '- 防治措施：', '2025-08-21 20:59:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (283, 10, 7, '   - 物理：增加行距以减少叶面湿度，采用滴灌代替喷灌，避免叶面长时间潮湿。', '2025-08-21 20:59:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (284, 10, 8, '   - 药剂：铜制剂、链霉素交替使用，防止病菌产生耐药性。', '2025-08-21 20:59:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (285, 10, 9, '   - 管理：清除病残体，避免使用带病苗，减少病源基数。', '2025-08-21 20:59:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (286, 10, 10, '   - 外部环境调控：降低棚内湿度，改善通风条件。', '2025-08-21 20:59:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (287, 10, 11, '   - 土壤管理：避免过度灌水，保持土壤湿度在 60–70%。', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (288, 10, 12, '   - 营养调控：氮肥过多易加重病害，需减少氮肥施用量。', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (289, 10, 13, '2. Anthracnose Fruit Rot（炭疽病果腐）', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (290, 10, 14, '- 病原与传播：由 Colletotrichum acutatum 引起，高温高湿条件下快速传播。', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (291, 10, 15, '- 症状：果实出现黑色凹陷病斑，湿度大时病斑上长出粉红色黏孢子团。', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (292, 10, 16, '- 危害：采前采后均可发病，采后贮藏期易腐烂，导致严重产量损失。', '2025-08-21 20:59:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (293, 10, 17, '- 环境与诱发条件：高温高湿（温度 > 28℃、空气湿度 > 80%）、氮肥过多时病害易爆发。', '2025-08-21 20:59:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (294, 10, 18, '- 防治措施：', '2025-08-21 20:59:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (295, 10, 19, '   - 物理：避免果实接触地面，采后采用低温冷链贮藏，抑制病菌繁殖。', '2025-08-21 20:59:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (296, 10, 20, '   - 药剂：吡唑醚菌酯、苯醚甲环唑、啶酰菌胺交替使用，降低耐药风险。', '2025-08-21 20:59:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (297, 10, 21, '   - 管理：及时清除病果，避免连作，减少病菌积累。', '2025-08-21 20:59:52');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (298, 10, 22, '   - 外部环境调控：改善通风条件，保持空气湿度 < 75%。', '2025-08-21 20:59:52');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (299, 10, 23, '   - 土壤管理：避免积水，控制土壤湿度在 60–70%。', '2025-08-21 20:59:52');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (300, 10, 24, '   - 营养调控：减少氮肥施用量，补充钾肥以提高果实抗性。', '2025-08-21 20:59:52');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (301, 10, 25, '3. Gray Mold（灰霉病）', '2025-08-21 20:59:53');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (302, 10, 26, '- 病原与传播：由 Botrytis cinerea 引起，花器及幼果期感染最重，通过空气传播孢子。', '2025-08-21 20:59:53');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (303, 10, 27, '- 症状：果实表面出现灰色霉层，触碰即掉落孢子粉，后期果实腐烂。', '2025-08-21 20:59:53');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (304, 10, 28, '- 环境与诱发条件：', '2025-08-21 20:59:53');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (305, 10, 29, '   - 温度 15–20℃、相对湿度 > 85% 时最易爆发；', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (306, 10, 30, '   - 光照不足、果实表面长时间潮湿会加重病害。', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (307, 10, 31, '- 防治措施：', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (308, 10, 32, '   - 物理：加强通风以降低棚内湿度，避免果实相互挤压，减少接触传播。', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (309, 10, 33, '   - 药剂：腐霉利、异菌脲、嘧霉胺轮换使用，避免耐药性产生。', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (310, 10, 34, '   - 管理：及时采收病果，减少病源基数，降低扩散风险。', '2025-08-21 20:59:54');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (311, 10, 35, '   - 外部环境调控：加大通风量，避免棚内结露，减少高湿环境。', '2025-08-21 20:59:55');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (312, 10, 36, '   - 土壤管理：适度控水，避免叶片和果实接触湿土，降低感染概率。', '2025-08-21 20:59:55');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (313, 10, 37, '   - 营养调控：适量补钙，提高果实硬度，减少腐烂风险。', '2025-08-21 20:59:55');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (314, 10, 38, '4. Leaf Spot（叶斑病）', '2025-08-21 20:59:55');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (315, 10, 39, '- 病原与传播：由 Mycosphaerella fragariae 引起，通过气流或雨水传播。', '2025-08-21 20:59:56');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (316, 10, 40, '- 症状：叶片出现褐色小圆斑，边缘清晰，中部呈灰白色，影响光合作用。', '2025-08-21 20:59:56');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (317, 10, 41, '- 环境与诱发条件：温度 15–25℃、空气湿度 70–80% 时易发病；土壤 pH<5 时病害加重。', '2025-08-21 20:59:56');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (318, 10, 42, '- 防治措施：', '2025-08-21 20:59:56');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (319, 10, 43, '   - 物理：减少叶片潮湿时间，避免密植，改善植株间通风透光性。', '2025-08-21 20:59:56');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (320, 10, 44, '   - 药剂：代森锰锌、氯溴异氰尿酸喷施防治。', '2025-08-21 20:59:57');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (321, 10, 45, '   - 管理：选择抗病品种，注意轮作，减少病菌积累。', '2025-08-21 20:59:57');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (322, 10, 46, '   - 外部环境调控：及时摘除病叶，降低田间病菌密度。', '2025-08-21 20:59:57');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (323, 10, 47, '   - 土壤管理：调节土壤 pH 至 5.5–6.5，创造不适宜病菌繁殖的环境。', '2025-08-21 20:59:57');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (324, 10, 48, '   - 营养调控：氮肥过多会加重病害，需控制氮肥施用量。', '2025-08-21 20:59:58');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (325, 10, 49, '5. Powdery Mildew Fruit（果实白粉病）', '2025-08-21 20:59:58');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (326, 10, 50, '- 病原与传播：由 Podosphaera aphanis 引起，通过气流传播孢子。', '2025-08-21 20:59:58');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (327, 10, 51, '- 症状：果实表面覆盖白色粉层，导致果实变形，商品率显著下降。', '2025-08-21 20:59:58');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (328, 10, 52, '- 环境与诱发条件：', '2025-08-21 20:59:58');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (329, 10, 53, '   - 温暖干燥（20–25℃）、通风不良的温室环境易发；', '2025-08-21 20:59:59');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (330, 10, 54, '   - 氮肥过多会加重病害。', '2025-08-21 20:59:59');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (331, 10, 55, '- 防治措施：', '2025-08-21 20:59:59');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (332, 10, 56, '   - 物理：改善通风条件，避免湿热闷棚环境。', '2025-08-21 20:59:59');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (333, 10, 57, '   - 药剂：三唑类（戊唑醇）、硫制剂交替使用，提高防治效果。', '2025-08-21 21:00:00');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (334, 10, 58, '   - 管理：选用无病苗木，避免带病栽培，减少初始病源。', '2025-08-21 21:00:00');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (335, 10, 59, '   - 外部环境调控：增加空气流通，降低局部湿度，抑制孢子萌发。', '2025-08-21 21:00:00');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (336, 10, 60, '   - 土壤管理：控制氮肥用量，保持土壤电导率（EC）<1.2 mS/cm，避免盐害影响植株抗性。', '2025-08-21 21:00:00');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (337, 10, 61, '   - 营养调控：补充钾肥，增强果实抗性，减少病害发生。', '2025-08-21 21:00:01');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (338, 10, 62, '6. Powdery Mildew Leaf（叶片白粉病）', '2025-08-21 21:00:01');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (339, 10, 63, '- 病原与传播：由 Podosphaera aphanis 引起，与果实白粉病同源，通过气流传播。', '2025-08-21 21:00:01');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (340, 10, 64, '- 症状：叶片正反面均出现白色粉层，导致叶片卷曲，光合作用效率下降。', '2025-08-21 21:00:02');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (341, 10, 65, '- 环境与诱发条件：高湿 + 高氮环境、弱光条件下易爆发。', '2025-08-21 21:00:02');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (342, 10, 66, '- 防治措施：', '2025-08-21 21:00:02');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (343, 10, 67, '   - 物理：温室内加强通风，降低湿度，改善光照条件。', '2025-08-21 21:00:02');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (344, 10, 68, '   - 药剂：多抗霉素、硫磺悬浮剂喷施防治。', '2025-08-21 21:00:03');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (345, 10, 69, '   - 管理：避免连作，合理密植，减少植株间湿度积累。', '2025-08-21 21:00:03');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (346, 10, 70, '   - 外部环境调控：降低空气湿度，增强光照强度，抑制病菌生长。', '2025-08-21 21:00:03');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (347, 10, 71, '   - 土壤管理：控制氮肥水平，避免土壤氮含量 > 150 mg/kg，减少植株徒长。', '2025-08-21 21:00:03');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (348, 10, 72, '   - 营养调控：补充钙、钾肥，提升植株整体抗病性。', '2025-08-21 21:00:04');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (349, 11, 0, '1. Angular Leafspot（角斑病）', '2025-08-21 21:01:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (350, 11, 1, '- 病原与传播：由 Xanthomonas fragariae 引起，细菌性病害，主要通过雨水、灌溉水传播。', '2025-08-21 21:01:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (351, 11, 2, '- 症状：叶片出现水浸状小斑点，逐渐发展为褐色坏死斑，严重时叶片枯死。', '2025-08-21 21:01:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (352, 11, 3, '- 环境与诱发条件：', '2025-08-21 21:01:17');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (353, 11, 4, '   - 低温高湿（15–20℃）时易发；', '2025-08-21 21:01:18');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (354, 11, 5, '   - 高湿度环境（空气湿度 > 80%、土壤湿度过高）会加重病害。', '2025-08-21 21:01:18');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (355, 11, 6, '- 防治措施：', '2025-08-21 21:01:18');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (356, 11, 7, '   - 物理：增加行距以减少叶面湿度，采用滴灌代替喷灌，避免叶面长时间潮湿。', '2025-08-21 21:01:18');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (357, 11, 8, '   - 药剂：铜制剂、链霉素交替使用，防止病菌产生耐药性。', '2025-08-21 21:01:19');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (358, 11, 9, '   - 管理：清除病残体，避免使用带病苗，减少病源基数。', '2025-08-21 21:01:19');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (359, 11, 10, '   - 外部环境调控：降低棚内湿度，改善通风条件。', '2025-08-21 21:01:19');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (360, 11, 11, '   - 土壤管理：避免过度灌水，保持土壤湿度在 60–70%。', '2025-08-21 21:01:19');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (361, 11, 12, '   - 营养调控：氮肥过多易加重病害，需减少氮肥施用量。', '2025-08-21 21:01:20');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (362, 11, 13, '2. Anthracnose Fruit Rot（炭疽病果腐）', '2025-08-21 21:01:20');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (363, 11, 14, '- 病原与传播：由 Colletotrichum acutatum 引起，高温高湿条件下快速传播。', '2025-08-21 21:01:20');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (364, 11, 15, '- 症状：果实出现黑色凹陷病斑，湿度大时病斑上长出粉红色黏孢子团。', '2025-08-21 21:01:20');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (365, 11, 16, '- 危害：采前采后均可发病，采后贮藏期易腐烂，导致严重产量损失。', '2025-08-21 21:01:21');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (366, 11, 17, '- 环境与诱发条件：高温高湿（温度 > 28℃、空气湿度 > 80%）、氮肥过多时病害易爆发。', '2025-08-21 21:01:21');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (367, 11, 18, '- 防治措施：', '2025-08-21 21:01:21');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (368, 11, 19, '   - 物理：避免果实接触地面，采后采用低温冷链贮藏，抑制病菌繁殖。', '2025-08-21 21:01:21');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (369, 11, 20, '   - 药剂：吡唑醚菌酯、苯醚甲环唑、啶酰菌胺交替使用，降低耐药风险。', '2025-08-21 21:01:21');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (370, 11, 21, '   - 管理：及时清除病果，避免连作，减少病菌积累。', '2025-08-21 21:01:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (371, 11, 22, '   - 外部环境调控：改善通风条件，保持空气湿度 < 75%。', '2025-08-21 21:01:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (372, 11, 23, '   - 土壤管理：避免积水，控制土壤湿度在 60–70%。', '2025-08-21 21:01:22');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (373, 11, 24, '   - 营养调控：减少氮肥施用量，补充钾肥以提高果实抗性。', '2025-08-21 21:01:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (374, 11, 25, '3. Gray Mold（灰霉病）', '2025-08-21 21:01:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (375, 11, 26, '- 病原与传播：由 Botrytis cinerea 引起，花器及幼果期感染最重，通过空气传播孢子。', '2025-08-21 21:01:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (376, 11, 27, '- 症状：果实表面出现灰色霉层，触碰即掉落孢子粉，后期果实腐烂。', '2025-08-21 21:01:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (377, 11, 28, '- 环境与诱发条件：', '2025-08-21 21:01:23');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (378, 11, 29, '   - 温度 15–20℃、相对湿度 > 85% 时最易爆发；', '2025-08-21 21:01:24');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (379, 11, 30, '   - 光照不足、果实表面长时间潮湿会加重病害。', '2025-08-21 21:01:24');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (380, 11, 31, '- 防治措施：', '2025-08-21 21:01:24');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (381, 11, 32, '   - 物理：加强通风以降低棚内湿度，避免果实相互挤压，减少接触传播。', '2025-08-21 21:01:24');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (382, 11, 33, '   - 药剂：腐霉利、异菌脲、嘧霉胺轮换使用，避免耐药性产生。', '2025-08-21 21:01:24');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (383, 11, 34, '   - 管理：及时采收病果，减少病源基数，降低扩散风险。', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (384, 11, 35, '   - 外部环境调控：加大通风量，避免棚内结露，减少高湿环境。', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (385, 11, 36, '   - 土壤管理：适度控水，避免叶片和果实接触湿土，降低感染概率。', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (386, 11, 37, '   - 营养调控：适量补钙，提高果实硬度，减少腐烂风险。', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (387, 11, 38, '4. Leaf Spot（叶斑病）', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (388, 11, 39, '- 病原与传播：由 Mycosphaerella fragariae 引起，通过气流或雨水传播。', '2025-08-21 21:01:25');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (389, 11, 40, '- 症状：叶片出现褐色小圆斑，边缘清晰，中部呈灰白色，影响光合作用。', '2025-08-21 21:01:26');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (390, 11, 41, '- 环境与诱发条件：温度 15–25℃、空气湿度 70–80% 时易发病；土壤 pH<5 时病害加重。', '2025-08-21 21:01:26');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (391, 11, 42, '- 防治措施：', '2025-08-21 21:01:26');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (392, 11, 43, '   - 物理：减少叶片潮湿时间，避免密植，改善植株间通风透光性。', '2025-08-21 21:01:26');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (393, 11, 44, '   - 药剂：代森锰锌、氯溴异氰尿酸喷施防治。', '2025-08-21 21:01:27');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (394, 11, 45, '   - 管理：选择抗病品种，注意轮作，减少病菌积累。', '2025-08-21 21:01:27');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (395, 11, 46, '   - 外部环境调控：及时摘除病叶，降低田间病菌密度。', '2025-08-21 21:01:27');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (396, 11, 47, '   - 土壤管理：调节土壤 pH 至 5.5–6.5，创造不适宜病菌繁殖的环境。', '2025-08-21 21:01:27');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (397, 11, 48, '   - 营养调控：氮肥过多会加重病害，需控制氮肥施用量。', '2025-08-21 21:01:27');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (398, 11, 49, '5. Powdery Mildew Fruit（果实白粉病）', '2025-08-21 21:01:28');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (399, 11, 50, '- 病原与传播：由 Podosphaera aphanis 引起，通过气流传播孢子。', '2025-08-21 21:01:28');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (400, 11, 51, '- 症状：果实表面覆盖白色粉层，导致果实变形，商品率显著下降。', '2025-08-21 21:01:28');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (401, 11, 52, '- 环境与诱发条件：', '2025-08-21 21:01:28');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (402, 11, 53, '   - 温暖干燥（20–25℃）、通风不良的温室环境易发；', '2025-08-21 21:01:29');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (403, 11, 54, '   - 氮肥过多会加重病害。', '2025-08-21 21:01:29');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (404, 11, 55, '- 防治措施：', '2025-08-21 21:01:29');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (405, 11, 56, '   - 物理：改善通风条件，避免湿热闷棚环境。', '2025-08-21 21:01:29');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (406, 11, 57, '   - 药剂：三唑类（戊唑醇）、硫制剂交替使用，提高防治效果。', '2025-08-21 21:01:29');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (407, 11, 58, '   - 管理：选用无病苗木，避免带病栽培，减少初始病源。', '2025-08-21 21:01:30');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (408, 11, 59, '   - 外部环境调控：增加空气流通，降低局部湿度，抑制孢子萌发。', '2025-08-21 21:01:30');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (409, 11, 60, '   - 土壤管理：控制氮肥用量，保持土壤电导率（EC）<1.2 mS/cm，避免盐害影响植株抗性。', '2025-08-21 21:01:30');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (410, 11, 61, '   - 营养调控：补充钾肥，增强果实抗性，减少病害发生。', '2025-08-21 21:01:30');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (411, 11, 62, '6. Powdery Mildew Leaf（叶片白粉病）', '2025-08-21 21:01:31');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (412, 11, 63, '- 病原与传播：由 Podosphaera aphanis 引起，与果实白粉病同源，通过气流传播。', '2025-08-21 21:01:31');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (413, 11, 64, '- 症状：叶片正反面均出现白色粉层，导致叶片卷曲，光合作用效率下降。', '2025-08-21 21:01:31');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (414, 11, 65, '- 环境与诱发条件：高湿 + 高氮环境、弱光条件下易爆发。', '2025-08-21 21:01:31');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (415, 11, 66, '- 防治措施：', '2025-08-21 21:01:31');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (416, 11, 67, '   - 物理：温室内加强通风，降低湿度，改善光照条件。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (417, 11, 68, '   - 药剂：多抗霉素、硫磺悬浮剂喷施防治。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (418, 11, 69, '   - 管理：避免连作，合理密植，减少植株间湿度积累。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (419, 11, 70, '   - 外部环境调控：降低空气湿度，增强光照强度，抑制病菌生长。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (420, 11, 71, '   - 土壤管理：控制氮肥水平，避免土壤氮含量 > 150 mg/kg，减少植株徒长。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (421, 11, 72, '   - 营养调控：补充钙、钾肥，提升植株整体抗病性。', '2025-08-21 21:01:32');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (422, 12, 0, '1. 生长周期大致时间线（温室栽培条件下）', '2025-08-22 09:20:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (423, 12, 1, '- 育苗期：30–40 天（约 4–6 周）', '2025-08-22 09:20:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (424, 12, 2, '- 营养生长期：30–40 天（约 4–6 周）', '2025-08-22 09:20:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (425, 12, 3, '- 开花期：20–25 天（约 3–4 周）', '2025-08-22 09:20:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (426, 12, 4, '- 果实膨大期：25–30 天（约 4–5 周）', '2025-08-22 09:20:48');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (427, 12, 5, '- 成熟采收期：20–30 天（约 3–4 周，可多批次采收）', '2025-08-22 09:20:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (428, 12, 6, '👉 合计：约 120–160 天（4–5 个月），即可进入 第一批果实采收。', '2025-08-22 09:20:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (429, 12, 7, '***', '2025-08-22 09:20:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (430, 12, 8, '2. 采收期范围', '2025-08-22 09:20:49');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (431, 12, 9, '- 草莓属于 连续采收型作物：一旦进入结果期，会持续开花、挂果、成熟。', '2025-08-22 09:20:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (432, 12, 10, '- 采收时间跨度：', '2025-08-22 09:20:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (433, 12, 11, '   - 首批果实成熟 → 定植后 3.5–5 个月左右', '2025-08-22 09:20:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (434, 12, 12, '   - 采收高峰期 → 持续 2–3 个月', '2025-08-22 09:20:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (435, 12, 13, '   - 总采收期 → 可维持 3–5 个月（视栽培方式和管理水平）', '2025-08-22 09:20:50');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (436, 12, 14, '***', '2025-08-22 09:20:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (437, 12, 15, '3. 举例说明', '2025-08-22 09:20:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (438, 12, 16, '- 秋季定植（9–10 月） → 翌年 1–2 月开始采收 → 可持续采收到 4–5 月', '2025-08-22 09:20:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (439, 12, 17, '- 早春定植（2–3 月） → 5–6 月采收 → 采收持续到 7–8 月', '2025-08-22 09:20:51');
INSERT INTO `knowledge_chunk` (`id`, `kb_id`, `chunk_index`, `content`, `create_time`) VALUES (440, 12, 18, '育苗期', '2025-08-22 09:20:51');
